BEGIN READ ONLY;
SELECT jsonb_build_object('kind','catalog_type','occasion_id',pt.occasion,'id',pt.id,'type',pt.type,'title',pt.title,'field_count',(SELECT count(*) FROM public.form_fields ff JOIN public.forms f ON f.id=ff.form WHERE ff.product_type=pt.id AND f.occasion=pt.occasion),'visible_field_count',(SELECT count(*) FROM public.form_fields ff JOIN public.forms f ON f.id=ff.form WHERE ff.product_type=pt.id AND f.occasion=pt.occasion AND NOT ff.is_hidden),'ordered_count',(SELECT count(*) FROM eshop.order_product_ticket opt JOIN eshop.products p ON p.id=opt.product WHERE p.product_type=pt.id)) FROM eshop.product_types pt JOIN public.occasions o ON o.id=pt.occasion WHERE o.organization=3 ORDER BY pt.occasion,pt.id;
SELECT jsonb_build_object('kind','integrity','cross_occasion_form_fields',(SELECT count(*) FROM public.form_fields ff JOIN public.forms fo ON fo.id=ff.form JOIN eshop.product_types pt ON pt.id=ff.product_type JOIN public.occasions o ON o.id=fo.occasion WHERE o.organization=3 AND pt.occasion IS DISTINCT FROM fo.occasion),'orphan_ticket_products',(SELECT count(*) FROM eshop.order_product_ticket opt JOIN eshop.tickets t ON t.id=opt.ticket JOIN public.occasions o ON o.id=t.occasion LEFT JOIN eshop.products p ON p.id=opt.product WHERE o.organization=3 AND p.id IS NULL),'cross_occasion_ticket_products',(SELECT count(*) FROM eshop.order_product_ticket opt JOIN eshop.tickets t ON t.id=opt.ticket JOIN public.occasions o ON o.id=t.occasion JOIN eshop.products p ON p.id=opt.product JOIN eshop.product_types pt ON pt.id=p.product_type WHERE o.organization=3 AND pt.occasion IS DISTINCT FROM t.occasion));
SELECT jsonb_build_object('kind','live_rpc','name',p.proname,'food_selector',position('food' in pg_get_functiondef(p.oid))>0,'has_short_title',position('short_title' in pg_get_functiondef(p.oid))>0,'has_title_short',position('title_short' in pg_get_functiondef(p.oid))>0) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('get_products_and_types','get_tickets_with_details','validate_ticket_layout');
COMMIT;
